#include "ferretdb_compat.h"
#include <sqlite3.h>
#include <string.h>
static int scalar(sqlite3*d,const char*q,int expected){sqlite3_stmt*s;int ok;if(sqlite3_prepare_v2(d,q,-1,&s,NULL)!=SQLITE_OK)return 0;ok=sqlite3_step(s)==SQLITE_ROW&&sqlite3_column_int(s,0)==expected;sqlite3_finalize(s);return ok;}
WenaFerretFormat wena_ferretdb_probe_readonly(const char*p){static const char*q="SELECT count(*) FROM _ferretdb_collections c JOIN sqlite_schema s ON s.type='table' AND s.name=c.table_name WHERE c.name IN('boards','lists','swimlanes','cards') AND json_valid(c.settings) AND json_extract(c.settings,'$.indexFormat')=2 AND s.sql LIKE '%_ferretdb_sjson TEXT NOT NULL%'";sqlite3*d=NULL;WenaFerretFormat f=WENA_FERRET_UNKNOWN;if(!p||p[0]!='/'||sqlite3_open_v2(p,&d,SQLITE_OPEN_READONLY|SQLITE_OPEN_FULLMUTEX,NULL)!=SQLITE_OK)goto done;if(sqlite3_exec(d,"PRAGMA query_only=ON;PRAGMA foreign_keys=ON;",NULL,NULL,NULL)!=SQLITE_OK)goto done;if(!scalar(d,"PRAGMA user_version",0)||!scalar(d,"PRAGMA application_id",0)||!scalar(d,q,4)||!scalar(d,"SELECT count(*) FROM pragma_quick_check WHERE quick_check='ok'",1))goto done;f=WENA_FERRET_V1_SJSON_INDEX2;done:if(d)sqlite3_close(d);return f;}
